import XCTest

final class HomeUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
    }

    override func tearDownWithError() throws {
        XCUIDevice.shared.orientation = .portrait
    }

    /// Toolbar buttons show up twice in the tree (the Button and its wrapper), so take the first match.
    private func element(_ id: String) -> XCUIElement {
        app.descendants(matching: .any)[id].firstMatch
    }

    // MARK: - HomeView

    // uitest: HomeView | - iPhone 세로: `home.screen` 이 보이고 `home.drawer` 는 없다
    @MainActor func test_HomeView_iPhonePortraitShowsScreenWithoutDrawer() throws {
        guard UIDevice.current.userInterfaceIdiom == .phone else { throw XCTSkip("iPhone 전용") }
        XCUIDevice.shared.orientation = .portrait
        XCTAssertTrue(element("home.screen").waitForExistence(timeout: 5))
        XCTAssertFalse(element("home.drawer").waitForExistence(timeout: 2))
    }

    // uitest: HomeView | - iPhone 가로로 돌리면: `home.drawer` 와 `home.screen` 이 함께 보인다
    @MainActor func test_HomeView_iPhoneLandscapeShowsDrawerAndScreen() throws {
        guard UIDevice.current.userInterfaceIdiom == .phone else { throw XCTSkip("iPhone 전용") }
        XCUIDevice.shared.orientation = .portrait
        XCTAssertTrue(element("home.screen").waitForExistence(timeout: 5))
        XCUIDevice.shared.orientation = .landscapeLeft
        XCTAssertTrue(element("home.drawer").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.screen").waitForExistence(timeout: 5))
    }

    // uitest: HomeView | - iPad: `home.drawer` 와 `home.screen` 가 보인다
    @MainActor func test_HomeView_iPadShowsDrawerAndScreen() throws {
        guard UIDevice.current.userInterfaceIdiom == .pad else { throw XCTSkip("iPad 전용") }
        XCTAssertTrue(element("home.drawer").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.screen").waitForExistence(timeout: 5))
    }

    // uitest: HomeView | - 공통 : `home.newJournalButton` 가 보인다
    @MainActor func test_HomeView_showsNewJournalButton() throws {
        let button = element("home.newJournalButton")
        XCTAssertTrue(button.waitForExistence(timeout: 5))
        XCTAssertTrue(button.isHittable)
    }

    // MARK: - HomeSidebarView

    // uitest: HomeSidebarView | - 토글 버튼을 눌렀을 때 캘린더 상태와 리스트 상태가 번갈아 바뀌는지 확인한다.
    @MainActor func test_HomeSidebarView_toggleSwitchesCalendarAndList() throws {
        if UIDevice.current.userInterfaceIdiom == .phone {
            XCUIDevice.shared.orientation = .landscapeLeft
        }
        XCTAssertTrue(element("home.drawer").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.drawer.seeAll").waitForExistence(timeout: 5))
        XCTAssertFalse(element("home.drawer.calendar.month").waitForExistence(timeout: 2))

        element("home.drawer.calendarToggle").tap()
        XCTAssertTrue(element("home.drawer.calendar.month").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.drawer.calendar.prev").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.drawer.calendar.next").waitForExistence(timeout: 5))
        XCTAssertFalse(element("home.drawer.seeAll").waitForExistence(timeout: 2))

        element("home.drawer.calendarToggle").tap()
        XCTAssertTrue(element("home.drawer.seeAll").waitForExistence(timeout: 5))
        XCTAssertFalse(element("home.drawer.calendar.month").waitForExistence(timeout: 2))
    }

    // MARK: - HomeContentView

    // uitest: HomeContentView | - 공통: `home.greeting` 과 `home.date` 가 보인다
    @MainActor func test_HomeContentView_showsGreetingAndDate() throws {
        XCTAssertTrue(element("home.greeting").waitForExistence(timeout: 5))
        XCTAssertTrue(element("home.date").waitForExistence(timeout: 5))
    }
}
